import{_ as n,c as l,a as o,b as d,d as s,w as r,r as i,o as p,e as a}from"./app-__pB_IG8.js";const c={},h={class:"table-of-contents"};function u(g,t){const e=i("router-link");return p(),l("div",null,[t[7]||(t[7]=o("h1",{id:"bootstrap-简介",tabindex:"-1"},[o("a",{class:"header-anchor",href:"#bootstrap-简介"},[o("span",null,"Bootstrap 简介")])],-1)),o("nav",h,[o("ul",null,[o("li",null,[s(e,{to:"#是什么"},{default:r(()=>t[0]||(t[0]=[a("是什么")])),_:1,__:[0]})]),o("li",null,[s(e,{to:"#版本简史-关键分水岭"},{default:r(()=>t[1]||(t[1]=[a("版本简史（关键分水岭）")])),_:1,__:[1]})]),o("li",null,[s(e,{to:"#核心概念"},{default:r(()=>t[2]||(t[2]=[a("核心概念")])),_:1,__:[2]})]),o("li",null,[s(e,{to:"#和「上古后台模板」的关系"},{default:r(()=>t[3]||(t[3]=[a("和「上古后台模板」的关系")])),_:1,__:[3]})]),o("li",null,[s(e,{to:"#为什么热度下降"},{default:r(()=>t[4]||(t[4]=[a("为什么热度下降")])),_:1,__:[4]})]),o("li",null,[s(e,{to:"#现在还值得用吗"},{default:r(()=>t[5]||(t[5]=[a("现在还值得用吗")])),_:1,__:[5]})]),o("li",null,[s(e,{to:"#小结"},{default:r(()=>t[6]||(t[6]=[a("小结")])),_:1,__:[6]})])])]),t[8]||(t[8]=d('<div class="hint-container tip"><p class="hint-container-title">一句话</p><p>Bootstrap 是把「响应式栅格 + 预制组件」普及开来的奠基级前端 UI 框架；它的 class 驱动 + jQuery 插件范式已被现代组件库和 Tailwind 取代，但海量存量后台系统里仍绕不开。</p></div><h2 id="是什么" tabindex="-1"><a class="header-anchor" href="#是什么"><span>是什么</span></a></h2><p>Bootstrap 是一套由 Twitter 团队开源的<strong>前端 UI 框架</strong>（HTML / CSS / JS 组件库），2011 年发布。它让开发者不用从零写样式，下载引入就能得到一套统一、响应式的页面外观。核心是三件套：</p><ul><li><strong>栅格系统（Grid）</strong>：用 <code>.row</code> + <code>.col-*-*</code> 把页面切成 12 列响应式布局，手机 / 平板 / 桌面自动适配。这是它对前端最大的贡献。</li><li><strong>预制组件</strong>：按钮、表单、导航栏、卡片、模态框、表格、分页等，加 class 即有效果。</li><li><strong>工具类（Utilities）</strong>：<code>mt-3</code>（外边距）、<code>text-center</code>、<code>d-flex</code> 这类原子类快速调样式。</li><li><strong>JS 插件</strong>：下拉、弹窗、轮播、提示框等交互，早期依赖 <strong>jQuery</strong>，Bootstrap 5 已彻底移除 jQuery 依赖。</li></ul><h2 id="版本简史-关键分水岭" tabindex="-1"><a class="header-anchor" href="#版本简史-关键分水岭"><span>版本简史（关键分水岭）</span></a></h2><table><thead><tr><th>版本</th><th>年份</th><th>关键变化</th></tr></thead><tbody><tr><td>2.x</td><td>2012</td><td>早期栅格，兼容 IE7+</td></tr><tr><td>3.x</td><td>2013</td><td><strong>移动优先</strong>重构，栅格重做，最经典、存量最多（大量 Ace Admin 类后台模板基于它）</td></tr><tr><td>4.x</td><td>2018</td><td>改用 Flexbox 栅格，Sass 重写，放弃 IE9-</td></tr><tr><td>5.x</td><td>2021</td><td><strong>去掉 jQuery</strong>，纯原生 JS；新增 RTL、CSS 变量、离线粒子等</td></tr></tbody></table><blockquote><p>3.x 是最经典的一代：很多 2015–2020 年的企业 / 政府 / 金融后台都基于 Bootstrap 3 模板搭建，至今仍在维护。</p></blockquote><h2 id="核心概念" tabindex="-1"><a class="header-anchor" href="#核心概念"><span>核心概念</span></a></h2><ul><li><strong>12 列栅格</strong>：一行 <code>.row</code> 内放若干 <code>.col-md-6</code> 等，总宽按 12 等分。配合断点前缀（<code>xs/sm/md/lg/xl</code>）实现不同屏幕不同布局。</li><li><strong>响应式断点</strong>：以视口宽度为阈值切换样式，移动优先（默认手机样式，再向上增强）。</li><li><strong>组件 + 工具类双层</strong>：大块结构用组件 class，细节微调用工具类，减少自定义 CSS。</li><li><strong>JS 插件与 jQuery</strong>：Bootstrap 3/4 的弹窗、下拉等靠 jQuery 选择器 + 事件绑定驱动；这和 AngularJS / Vue 的「声明式渲染、框架管 DOM」范式天然冲突——插件在元素被框架插入 DOM 之前扫描就找不到目标（典型的「动态 DOM 漏初始化」坑，详见本站 AngularJS 生命周期一文）。</li></ul><h2 id="和「上古后台模板」的关系" tabindex="-1"><a class="header-anchor" href="#和「上古后台模板」的关系"><span>和「上古后台模板」的关系</span></a></h2><p>你在本站看到的 Ace Admin 模板简介，其底座就是 <strong>Bootstrap 3 + jQuery</strong>。这类模板在「组件化框架」普及之前是后台开发的主流：下载 HTML 改改就能用。</p><p>但时代变化后，它的范式成了负担：</p><ul><li>jQuery 命令式操作 DOM，与 AngularJS / React / Vue 的声明式生命周期错位；</li><li>预制组件固定，想深度定制要覆盖大量变量，不如 Tailwind / CSS-in-JS 灵活。</li></ul><p>所以这类系统今天的价值主要是「<strong>维护存量时的踩坑参考</strong>」，而非新项目的选型目标。</p><h2 id="为什么热度下降" tabindex="-1"><a class="header-anchor" href="#为什么热度下降"><span>为什么热度下降</span></a></h2><ol><li><strong>Utility-first 崛起</strong>：Tailwind CSS 用原子类组合样式，比 Bootstrap 的「预制组件套 class」更灵活、不绑死设计语言，新项目更爱用。</li><li><strong>组件库自带样式</strong>：Vue / React 时代，<code>Element Plus</code>、<code>Ant Design</code> 把布局 + 组件 + 主题全包了，通常不需要再引 Bootstrap 做底座。</li><li><strong>定制成本高</strong>：Bootstrap 想改主题色 / 圆角得覆盖大量 Sass 变量或手写大量覆盖样式，不如新方案顺手。</li></ol><h2 id="现在还值得用吗" tabindex="-1"><a class="header-anchor" href="#现在还值得用吗"><span>现在还值得用吗</span></a></h2><table><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>新中后台项目</td><td>直接用 <code>Element Plus</code> / <code>Ant Design</code> 等组件库，一般不单独引 Bootstrap</td></tr><tr><td>通用 / 静态站点</td><td>想快速出带样式的页面、又不想引组件库，Bootstrap 5（无 jQuery）仍是最省事方案之一</td></tr><tr><td>维护存量系统</td><td>大量 2015–2020 后台基于 Bootstrap 3/4，绕不开，当「踩坑参考」即可</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">提醒</p><ul><li>新项目别再基于 Bootstrap 3 + jQuery 模板（如 Ace Admin）起步，它和现代框架生命周期冲突、维护成本高。</li><li>若要用 Bootstrap，优先 <strong>5.x</strong>（已去 jQuery）；4.x 尚可，3.x 已不建议新引入。</li><li>选型上，中后台闭眼组件库，轻量通用页可 Tailwind 或 Bootstrap 5，三者不必混用。</li></ul></div><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结"><span>小结</span></a></h2><p>Bootstrap 是响应式栅格与预制组件的开创者，定义了「移动优先」的页面范式；随着 Tailwind 与组件库兴起，它作为「新项目底座」的角色退场，但在存量系统里仍极常见。理解它，主要价值在于维护和排查那批 jQuery 时代的老后台。</p>',21))])}const b=n(c,[["render",u]]),f=JSON.parse('{"path":"/web/bootstrap.html","title":"Bootstrap 简介","lang":"zh-CN","frontmatter":{"title":"Bootstrap 简介","date":"2026-09-01T07:35:44.000Z","category":["others"],"tags":["Web","前端","Bootstrap"]},"git":{"updatedTime":1788744322000,"contributors":[{"name":"zhaomy","username":"zhaomy","email":"3036190149@qq.com","commits":2,"url":"https://github.com/zhaomy"}],"changelog":[{"hash":"d034417d8110be2fcfe05cfd1b0ce46d043b5d15","time":1788744322000,"email":"3036190149@qq.com","author":"zhaomy","message":"docs: Web 板块从 docs/others/web/ 迁到 docs/web/"},{"hash":"fe673822108b8ce30d9d298b32ed6771fbd8ef7e","time":1788400887000,"email":"3036190149@qq.com","author":"zhaomy","message":"docs: 重构 Web 分组并迁移 nvm 文章"}]},"filePathRelative":"web/bootstrap.md","excerpt":"\\n\\n<div class=\\"hint-container tip\\">\\n<p class=\\"hint-container-title\\">一句话</p>\\n<p>Bootstrap 是把「响应式栅格 + 预制组件」普及开来的奠基级前端 UI 框架；它的 class 驱动 + jQuery 插件范式已被现代组件库和 Tailwind 取代，但海量存量后台系统里仍绕不开。</p>\\n</div>\\n<h2>是什么</h2>\\n<p>Bootstrap 是一套由 Twitter 团队开源的<strong>前端 UI 框架</strong>（HTML / CSS / JS 组件库），2011 年发布。它让开发者不用从零写样式，下载引入就能得到一套统一、响应式的页面外观。核心是三件套：</p>"}');export{b as comp,f as data};
